content.content:
    # transiently doubling peak RSS on a large CSV.
    raw.seek(0)
    sep = sniff_delimiter(raw.read(_SNIFF_BYTES))
    raw.seek(0)
    return pd.read_csv(raw, sep=sep, **kwargs)


