  // A suite's connection is its datasource — orchestration providers (ADF/
  // Airflow) are never queryable, so they can't back a suite (CLAUDE.md §4, #242).
  const datasourceConnections = connections.filter((c) => CONNECTION_KIND[c.type] === 'datasource');

  // The target fields follow the active connection's datasource type: fixed on
  // edit, live-tracked from the picker on create.
  const watchedConnId = Form.useWatch('connection_id', form);
  const activeConnId = isEdit ? suite.connection_id : watchedConnId;
  const activeConn = connections.find((c) => c.id === activeConnId);
  const kind = activeConn ? targetKind(activeConn.type) : null;

  // Prefill once on mount/edit; create starts blank.
  useEffect(() => {
    if (suite) {
      const pattern = targetString(suite.target, 'pattern');
      const sampling = targetSampling(suite.target);
      form.setFieldsValue({
        name: suite.name,
        description: suite.description ?? undefined,
        connection_id: suite.connection_id,
        target_table: targetString(suite.target, 'table'),
        target_schema: targetString(suite.target, 'schema'),
        target_catalog: targetString(suite.target, 'catalog'),
        target_namespace: targetString(suite.target, 'namespace'),
        target_path: targetString(suite.target, 'path'),
        target_format: asFileFormat(targetString(suite.target, 'file_format')),
        target_mode: pattern ? 'batch' : 'single',
        target_prefix: targetString(suite.target, 'prefix'),
        target_pattern: pattern,
        target_strategy: asBatchStrategy(targetString(suite.target, 'strategy')) ?? 'latest',
        target_batch: targetString(suite.target, 'batch'),
        // A stored block IS the toggle — there is no separate "enabled" flag on the target, so its
        // presence is the only truth about whether this suite samples (#595).
        sampling_enabled: sampling !== undefined,
        sampling_strategy: sampling?.strategy ?? 'head',
        sampling_rows: sampling?.rows,
        sampling_seed: sampling?.seed,
      });
    }
  }, [suite, form]);

  const onSubmit = async () => {
    let values: SuiteFormValues;
    try {
      values = await form.validateFields();
    } catch {
      return; // validation errors render inline
    }
    // Assemble the datasource-shaped target; flag a partially-filled section inline rather than
    // letting the backend 422 on save.
    const { target, error } = kind
      ? assembleTarget(kind, values, {
          connType: activeConn?.type,
          stored: storedSampling(suite?.target),
        })
      : { target: null };
    if (error) {
      form.setFields([{ name: error.field, errors: [error.message] }]);
      return;
    }
    // The backend update treats a null target as "leave unchanged" (it never clears a target back
    // to NULL), so clearing the fields on a suite that has a target would silently keep the old
    // one. Say so rather than no-op.
    const hadTarget = isEdit && !!suite.target && Object.keys(suite.target).length > 0;
    if (hadTarget && target === null) {
      message.error('A run target can’t be removed once set — edit it to point elsewhere instead.');
      return;
    }
    await run(async () => {
      try {
        const saved = isEdit
          ? await updateSuite(suite.id, {
              name: values.name,
              description: values.description ?? null,
              target,
            })
          : await createSuite({
              name: values.name,
              description: values.description ?? null,
              connection_id: values.connection_id,
              target,
            });
        message.success(`${values.name}: ${isEdit ? 'saved' : 'created'}`);
        onSaved(saved);
      } catch (err) {
        // The sampling ↔ row-count refusal names two things that conflict, and a toast makes the
        // reader hold one of them in their head while going to look at the other.
        const api = apiFieldError(err);
        const blocked = api ? detailNames(api.detail, 'checks') : [];
        if (api?.code === 'suite_target_invalid' && blocked.length > 0) {
          form.setFields([
            {
              name: 'sampling_enabled',
              errors: [
                `${api.message.split(' Conflicting checks:')[0]} Conflicting ` +
                  `${blocked.length === 1 ? 'check' : 'checks'}: ${blocked.join(', ')}.`,
              ],
            },
          ]);
          return;
        }
        throw err;
      }
    });
  };

  return (
    <Form form={form} layout="vertical" onFinish={onSubmit}>
      <Form.Item name="name" label="Name" rules={[{ required: true }]}>
        <Input placeholder="Daily Revenue Audit" />
      </Form.Item>
      <Form.Item name="description" label="Description (optional)">
        <Input.TextArea rows={3} placeholder="What this suite validates and why." />
      </Form.Item>
      <Form.Item
        name="connection_id"
        label="Connection"
        rules={[{ required: true }]}
        extra={isEdit ? 'The connection is fixed once a suite is created.' : undefined}
      >
        <Select
          disabled={isEdit}
          placeholder="Select a datasource connection"
          options={datasourceConnections.map((c) => ({
            value: c.id,
            label: connectionOptionLabel(c),
          }))}
        />
      </Form.Item>
      {kind && (
        <TargetFields
          kind={kind}
          suiteId={isEdit ? suite.id : undefined}
          canSample={supportsSampling(activeConn?.type)}
        />
      )}
      <Flex justify="end" gap={8}>
        <Button onClick={onCancel}>Cancel</Button>
        <Button type="primary" htmlType="submit" loading={submitting}>
          {isEdit ? 'Save' : 'Create & add checks'}
        </Button>
      </Flex>
    </Form>
  );
}

/** The datasource-shaped run-target inputs. */
export function TargetFields({
  kind,
  suiteId,
  canSample = false,
}: {
  kind: TargetKind;
  suiteId?: string;
  /** Whether this connection's datasource accepts a `sampling` block (#595). */
  canSample?: boolean;
}) {
  const form = Form.useFormInstance();
  const mode = (Form.useWatch('target_mode', form) as 'single' | 'batch' | undefined) ?? 'single';
  const strategy =
    (Form.useWatch('target_strategy', form) as 'latest' | 'specific' | undefined) ?? 'latest';

  return (
    <>
      <Divider style={{ marginTop: 4 }} />
      <Flex vertical gap={2} style={{ marginBottom: 12 }}>
        <Typography.Text strong>Run target</Typography.Text>
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          Where this suite’s checks run. Optional — required to run the suite.
        </Typography.Text>
      </Flex>

      {kind === 'flatfile' ? (
        <>
          <Form.Item name="target_mode" label="Target mode" initialValue="single">
            <Radio.Group
              data-testid="flatfile-target-mode"
              optionType="button"
              size="small"
              options={[
                { label: 'Single file', value: 'single' },
                { label: 'Batch pattern', value: 'batch' },
              ]}
            />
          </Form.Item>
          {mode === 'batch' ? (
            <>
              <Form.Item
                name="target_prefix"
                label="Prefix (optional)"
                extra="Scopes the object listing, e.g. a container/folder path."
              >
                <Input placeholder="adls_flatfile/logistics_tracking/" />
              </Form.Item>
              <Form.Item
                name="target_pattern"
                label="Filename pattern (regex)"
                extra="The first capture group is the batch key — required for the 'specific' strategy."
              >
                <Input placeholder="tracking_events_([a-z_]+)\.csv" />
              </Form.Item>
              <Form.Item name="target_strategy" label="Strategy" initialValue="latest">
                <Select
                  options={[
                    { value: 'latest', label: 'Latest (greatest batch key)' },
                    { value: 'specific', label: 'Specific batch key' },
                  ]}
                />
              </Form.Item>
              {strategy === 'specific' && (
                <Form.Item
                  name="target_batch"
                  label="Batch key"
                  extra="The exact value the pattern's capture group must match."
                >
                  <Input placeholder="ready" />
                </Form.Item>
              )}
              <BatchPreviewHint suiteId={suiteId} />
            </>
          ) : (
            <>
              <Form.Item name="target_path" label="File path">
                <Input placeholder="container/path/to/data.csv" />
              </Form.Item>
              <Form.Item name="target_format" label="File format">
                <Select
                  allowClear
                  placeholder="Infer from extension"
                  options={[
                    { value: 'csv', label: 'CSV' },
                    { value: 'parquet', label: 'Parquet' },
                  ]}
                />
              </Form.Item>
            </>
          )}
        </>
      ) : kind === 'iceberg' ? (
        <>
          {/* Iceberg addresses a table by `namespace.table` (no SQL schema). Put the
              namespace in its own field — don't also dot-qualify Table, or the two
              fold to `namespace.namespace.table`. */}
          <Form.Item name="target_namespace" label="Namespace (optional)">
            <Input placeholder="sales" />
          </Form.Item>
          <Form.Item name="target_table" label="Table">
            <Input placeholder="orders" />
          </Form.Item>
        </>
      ) : (
        <>
          {kind === 'uc' && (
            <Form.Item name="target_catalog" label="Catalog">
              <Input placeholder="main" />
            </Form.Item>
          )}
          <Form.Item name="target_schema" label="Schema (optional)">
            <Input placeholder={kind === 'uc' ? 'default' : 'PUBLIC'} />
          </Form.Item>
          <Form.Item name="target_table" label="Table">
            <Input placeholder={kind === 'uc' ? 'orders' : 'ANALYTICS.ORDERS'} />
          </Form.Item>
        </>
      )}

      {canSample && <SamplingFields />}
    </>
  );
}

/**
 * The `sampling` authoring block (#595/#1325) — rendered only for the datasources whose runners
 * materialise rows (ADLS Gen2 / S3 / Unity Catalog).
 */
function SamplingFields() {
  const form = Form.useFormInstance();
  const enabled = Boolean(Form.useWatch('sampling_enabled', form));
  const strategy =
    (Form.useWatch('sampling_strategy', form) as 'head' | 'random' | undefined) ?? 'head';

  return (
    <>
      <Divider style={{ marginTop: 4 }} />
      <Flex vertical gap={2} style={{ marginBottom: 12 }}>
        <Typography.Text strong>Sampling (optional)</Typography.Text>
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          Run this suite’s checks against a bounded sample instead of the whole dataset. Keeps a
          large target inside the worker’s memory — but every verdict then describes the sample, so
          a check can pass while failing rows sit outside it.
        </Typography.Text>
      </Flex>

      <Form.Item name="sampling_enabled" label="Read" initialValue={false}>
        <Radio.Group
          data-testid="sampling-enabled"
          optionType="button"
          size="small"
          options={[
            { label: 'Whole dataset', value: false },
            { label: 'A sample', value: true },
          ]}
        />
      </Form.Item>

      {enabled && (
        <>
          {/* "Sample strategy", not "Strategy" — the flat-file batch selector
              above already owns a field called Strategy, and two identically
              labelled controls in one form is an ambiguity for a screen reader
              and for anyone reading the saved target back. */}
          <Form.Item name="sampling_strategy" label="Sample strategy" initialValue="head">
            <Select
              data-testid="sampling-strategy"
              options={[
                { value: 'head', label: 'Head — the first rows in storage order (cheapest)' },
                { value: 'random', label: 'Random — drawn uniformly across the dataset' },
              ]}
            />
          </Form.Item>
          <Form.Item
            name="sampling_rows"
            label="Rows"
            extra={`How many rows the checks see. Up to ${MAX_SAMPLE_ROWS.toLocaleString()}.`}
          >
            <InputNumber
              data-testid="sampling-rows"
              min={1}
              max={MAX_SAMPLE_ROWS}
              step={1000}
              precision={0}
              style={{ width: '100%' }}
              placeholder="100000"
            />
          </Form.Item>
          {strategy === 'random' && (
            <Form.Item
              name="sampling_seed"
              label="Seed (optional)"
              extra="Fixes the draw, so consecutive runs read the same rows and a change in verdict means a change in the data."
            >
              <InputNumber
                data-testid="sampling-seed"
                precision={0}
                style={{ width: '100%' }}
                placeholder="7"
              />
            </Form.Item>
          )}
        </>
      )}
    </>
  );
}

/**
 * The `error.code` values the batch preview (backend `services/run_target.py`) can 422 with — only
 * `batch_preview_no_data` gets its own canned copy below; every other 422 (a malformed pattern.
 */
const BATCH_PREVIEW_NO_DATA_CODE = 'batch_preview_no_data';

interface BatchPreviewErrorEnvelope {
  error?: { code?: string; detail?: { reason?: unknown } };
}

/**
 * Every non-idle state carries the exact spec it describes, so render can tell "this answer is
 * about what the form says now" from "this answer is about what the form said 300ms ago".
 */
type BatchPreviewSpec = string;

type BatchPreviewState =
  | { status: 'idle' }
  | { status: 'loading'; spec: BatchPreviewSpec }
  | {
      status: 'resolved';
      spec: BatchPreviewSpec;
      path: string;
      truncated: boolean;
      scanned: number;
    }
  | { status: 'no-match'; spec: BatchPreviewSpec; truncated: boolean; scanned: number }
  | { status: 'error'; spec: BatchPreviewSpec; message: string };

/**
 * Live "resolves to: `<path>`" hint next to the batch fields (#1193): debounces `GET
 * /suites/{id}/batch-preview` as prefix/pattern/strategy/batch change. The preview listing is
 * budget-bounded (#1243), so a `truncated` response is rendered as a hint, not a fact — it says
 * what the first `scanned` objects showed, not what's necessarily true of the whole prefix.
 */
function BatchPreviewHint({ suiteId }: { suiteId?: string }) {
  const form = Form.useFormInstance();
  const prefix = (Form.useWatch('target_prefix', form) as string | undefined)?.trim();
  const pattern = (Form.useWatch('target_pattern', form) as string | undefined)?.trim();
  const strategy =
    (Form.useWatch('target_strategy', form) as 'latest' | 'specific' | undefined) ?? 'latest';
  const batch = (Form.useWatch('target_batch', form) as string | undefined)?.trim();
  const active = Boolean(suiteId && pattern && !(strategy === 'specific' && !batch));
  // JSON so the four fields can't collide across boundaries (a prefix ending in
  // the separator vs a pattern starting with it).
  const spec: BatchPreviewSpec = JSON.stringify([prefix, pattern, strategy, batch]);

  const [state, setState] = useState<BatchPreviewState>({ status: 'idle' });
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  // The in-flight request for the CURRENT spec — aborted, not merely ignored, the moment a newer
  // spec supersedes it (#1243): a fast typist must not leave N live listings running server-side.
  const abortRef = useRef<AbortController | null>(null);
  useEffect(
    () => () => {
      clearTimeout(timer.current);
      abortRef.current?.abort();
    },
    [],
  );

  useEffect(() => {
    clearTimeout(timer.current);
    abortRef.current?.abort();
    if (!active) return;
    timer.current = setTimeout(() => {
      const controller = new AbortController();
      abortRef.current = controller;
      setState({ status: 'loading', spec });
      previewBatchTarget(
        suiteId as string,
        {
          pattern: pattern as string,
          strategy,
          ...(strategy === 'specific' ? { batch: batch as string } : {}),
          ...(prefix ? { prefix } : {}),
        },
        controller.signal,
      )
        .then((result) => {
          if (controller.signal.aborted) return;
          if (result.path === null) {
            setState({
              status: 'no-match',
              spec,
              truncated: result.truncated,
              scanned: result.scanned,
            });
            return;
          }
          setState({
            status: 'resolved',
            spec,
            path: result.path,
            truncated: result.truncated,
            scanned: result.scanned,
          });
        })
        .catch((err: unknown) => {
          if (controller.signal.aborted) return;
          const envelope = axios.isAxiosError(err)
            ? (err.response?.data as BatchPreviewErrorEnvelope | undefined)?.error
            : undefined;
          if (envelope?.code === BATCH_PREVIEW_NO_DATA_CODE) {
            setState({ status: 'no-match', spec, truncated: false, scanned: 0 });
            return;
          }
          // The 502's own message is deliberately generic ("could not list the datasource store")
          // because the backend must never echo an adapter exception.
          const reason = typeof envelope?.detail?.reason === 'string' ? envelope.detail.reason : '';
          const message = [errorMessage(err), reason].filter(Boolean).join(' ');
          setState({ status: 'error', spec, message });
        });
    }, 400);
  }, [active, suiteId, prefix, pattern, strategy, batch, spec]);

  if (!active || state.status === 'idle') return null;

  // The stored answer is about an older spec — a debounce is still ticking for
  // the current one. Show that, rather than a stale claim wearing a fresh label.
  if (state.spec !== spec || state.status === 'loading') {
    return (
      <Typography.Text type="secondary" style={{ fontSize: 12 }}>
        <LoadingOutlined style={{ marginRight: 4 }} />
        Checking the live listing…
      </Typography.Text>
    );
  }
  if (state.status === 'resolved') {
    return (
      <Typography.Text type="secondary" style={{ fontSize: 12 }}>
        Resolves to: <Typography.Text code>{state.path}</Typography.Text>
        {state.truncated &&
          ` (best match in the first ${state.scanned} objects scanned — may not be final)`}
      </Typography.Text>
    );
  }
  if (state.status === 'no-match') {
    return (
      <Typography.Text type="warning" style={{ fontSize: 12 }}>
        {state.truncated
          ? `No match in the first ${state.scanned} objects scanned — there may be more under this prefix than the preview could check.`
          : 'No file currently matches this pattern.'}
      </Typography.Text>
    );
  }
  return (
    <Typography.Text type="danger" style={{ fontSize: 12 }}>
      {state.message}
    </Typography.Text>
  );
}

"""The ADR 0040 table-enumeration seam — `enumerate_tables` on both providers."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from backend.app.lineage.warehouse_snowflake import SnowflakeLineageProvider
from backend.app.lineage.warehouse_unity_catalog import UnityCatalogLineageProvider

_FIXTURES = Path(__file__).parent.parent / "fixtures" / "lineage_native"

_SF_CONFIG: dict[str, object] = {"account": "ACMEORG-TEST01", "database": "DATAQ_DB"}
_UC_CONFIG: dict[str, object] = {"workspace_url": "https://dbc-1234abcd-5678.cloud.databricks.com"}


class _FakeResult:
    def __init__(self, rows: list[tuple[Any, ...]]) -> None:
        self._rows = rows

    def all(self) -> list[tuple[Any, ...]]:
        return self._rows


class _FakeConn:
    """Captures the SQL + params and returns canned rows — the same double shape
    the lineage-tier tests use (a fake cannot execute a WHERE clause, so the
    rows are what the real query WOULD return).
    """

    def __init__(self, rows: list[tuple[Any, ...]]) -> None:
        self.rows = rows
        self.sql: str = ""
        self.params: dict[str, Any] = {}

    def execute(self, clause: Any, params: dict[str, Any] | None = None) -> _FakeResult:
        self.sql = str(clause)
        self.params = params or {}
        return _FakeResult(self.rows)


def _sf_fixture_rows() -> list[tuple[Any, ...]]:
    """The real capture, narrowed to what the bound-catalog predicate would pass
    (the account-wide rows prove the OTHER catalogs exist to be excluded).
    """
    raw = json.loads((_FIXTURES / "snowflake_tables_casing.json").read_text())
    return [(r["TABLE_SCHEMA"], r["TABLE_NAME"]) for r in raw if r["TABLE_CATALOG"] == "DATAQ_DB"]


class TestUnityCatalogEnumeration:
    def test_real_capture_rows_become_lower_case_identities(self) -> None:
        raw = json.loads((_FIXTURES / "uc_tables_casing.json").read_text())
        rows = [
            (r["table_catalog"], r["table_schema"], r["table_name"])
            for r in raw
            if r["table_catalog"] not in ("system", "samples", "__databricks_internal")
            and r["table_schema"] != "information_schema"
        ]
        conn = _FakeConn(rows)
        idents = UnityCatalogLineageProvider().enumerate_tables(conn, connection_config=_UC_CONFIG)
        assert idents, "the capture holds real workspace tables"
        assert all(
            i.namespace == "unitycatalog://dbc-1234abcd-5678.cloud.databricks.com" for i in idents
        )
        # UC's information_schema returns lower-case; identities keep it verbatim.
        assert all(i.name == i.name.lower() for i in idents)

    def test_sql_scope_excludes_system_catalogs_and_information_schema(self) -> None:
        conn = _FakeConn([])
        UnityCatalogLineageProvider().enumerate_tables(conn, connection_config=_UC_CONFIG)
        assert "system.information_schema.tables" in conn.sql
        assert "table_catalog NOT IN ('system', 'samples', '__databricks_internal')" in conn.sql
        assert "table_schema != 'information_schema'" in conn.sql
        assert "table_catalog IS NOT NULL" in conn.sql  # budget-correct NULL exclusion
        assert "'STREAMING_TABLE'" in conn.sql

    def test_null_rows_are_skipped(self) -> None:
        conn = _FakeConn([("workspace", None, "t"), ("workspace", "s", "t")])
        idents = UnityCatalogLineageProvider().enumerate_tables(conn, connection_config=_UC_CONFIG)
        assert [i.name for i in idents] == ["workspace.s.t"]

def _read_env_file() -> dict[str, str]:
    """Best-effort parse of the gitignored repo-root .env (the POSTGRES_* creds that
    docker-compose + scripts/setup.sh use). Returns {} if it's absent.
    """
    env: dict[str, str] = {}
    path = Path(__file__).resolve().parents[2] / ".env"
    if path.exists():
        for raw in path.read_text().splitlines():
            line = raw.strip()
            if line and not line.startswith("#") and "=" in line:
                key, _, val = line.partition("=")
                env[key.strip()] = val.strip().strip('"').strip("'")
    return env


def _resolve_test_database_url() -> str | None:
    explicit = os.environ.get("TEST_DATABASE_URL")
    if explicit:
        return explicit
    env = _read_env_file()
    user, password = env.get("POSTGRES_USER"), env.get("POSTGRES_PASSWORD")
    if not (user and password):
        return None
    return f"REDACTED"
